import React, { useState, useEffect } from 'react';
import {
  View,
  Text,
  StyleSheet,
  ScrollView,
  TouchableOpacity,
  Alert,
  TextInput,
  Platform,
  Animated,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { useTheme } from '../theme/ThemeContext';
import { LinearGradient } from 'expo-linear-gradient';
import sharedFileStorage from '../utils/sharedFileStorage';

const ReceiveScreenWeb = () => {
  const { theme, isDarkMode } = useTheme();
  const [shareCode, setShareCode] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [receivedFile, setReceivedFile] = useState(null);
  const [fileType, setFileType] = useState(null); // 'encrypted' or 'unencrypted'

  const fadeAnim = React.useRef(new Animated.Value(0)).current;
  const slideAnim = React.useRef(new Animated.Value(30)).current;

  React.useEffect(() => {
    Animated.parallel([
      Animated.timing(fadeAnim, {
        toValue: 1,
        duration: 800,
        useNativeDriver: true,
      }),
      Animated.timing(slideAnim, {
        toValue: 0,
        duration: 600,
        useNativeDriver: true,
      }),
    ]).start();
  }, []);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (receivedFile && receivedFile.downloadUrl) {
        URL.revokeObjectURL(receivedFile.downloadUrl);
      }
    };
  }, [receivedFile]);

  // Validate share code format
  const validateShareCode = (code) => {
    const regex = /^[A-Z0-9]{6,8}$/;
    return regex.test(code.toUpperCase());
  };

  const testStorageAccess = () => {
    console.log('=== STORAGE TEST ===');
    console.log('Storage size:', sharedFileStorage.getStorageSize());
    console.log('All files:', sharedFileStorage.getAllFiles());

    // Test adding a dummy file
    const testFile = {
      id: 'TEST123',
      code: 'TEST123',
      fileName: 'test.txt',
      fileSize: 1000,
      fileType: 'text/plain',
      blobUrl: 'blob:test',
      expiryDate: new Date(Date.now() + 24 * 60 * 60 * 1000),
      createdAt: new Date(),
      downloadCount: 0,
    };

    sharedFileStorage.storeFile('TEST123', testFile);
    console.log('After adding test file, storage size:', sharedFileStorage.getStorageSize());
    console.log('Can retrieve test file:', sharedFileStorage.getFile('TEST123'));

    Alert.alert('Storage Test', `Storage size: ${sharedFileStorage.getStorageSize()}\\nCheck console for details`);
  };

  const accessSharedFile = async () => {
    if (!shareCode.trim()) {
      Alert.alert('Error', 'Please enter a share code');
      return;
    }

    const cleanCode = shareCode.toUpperCase().trim();

    if (!validateShareCode(cleanCode)) {
      Alert.alert('Invalid Code', 'Share code must be 6-8 characters (letters and numbers only)');
      return;
    }

    setIsLoading(true);

    // Simulate API call to retrieve file
    setTimeout(() => {
      setIsLoading(false);

      // Debug logging
      console.log('Looking for file with code:', cleanCode);
      console.log('Global storage size:', sharedFileStorage.getStorageSize());
      console.log('All files in storage:', sharedFileStorage.getAllFiles());

      // Try to get the file from shared storage
      const sharedFile = sharedFileStorage.getFile(cleanCode);

      console.log('Found shared file:', sharedFile);

      if (!sharedFile) {
        Alert.alert(
          'File Not Found', 
          'No file found with this share code. Please check the code and try again.'
        );
        return;
      }

      // Determine file type based on code length and actual type
      const isEncrypted = cleanCode.length === 8;
      const type = isEncrypted ? 'encrypted' : 'unencrypted';
      setFileType(type);

      // Create the file object for display
      const fileForDisplay = {
        id: sharedFile.code,
        name: sharedFile.fileName,
        originalName: sharedFile.fileName,
        size: sharedFile.fileSize,
        type: type,
        uploadedAt: sharedFile.createdAt.toISOString(),
        expiresAt: sharedFile.expiryDate.toISOString(),
        downloadUrl: sharedFile.blobUrl,
        blob: sharedFile.file,
        accessCount: sharedFile.accessCount,
      };

      setReceivedFile(fileForDisplay);
      Alert.alert(
        'File Found!', 
        `Found ${type} file: ${sharedFile.fileName}\\n\\nFile size: ${formatFileSize(sharedFile.fileSize)}\\n\\nYou can now download it.`
      );
    }, 1500);
  };

  const downloadFile = () => {
    if (!receivedFile || !receivedFile.downloadUrl) {
      Alert.alert('Error', 'No file available for download');
      return;
    }

    try {
      // Create download link
      const link = document.createElement('a');
      link.href = receivedFile.downloadUrl;

      // Use original filename or create a proper filename
      if (receivedFile.type === 'encrypted') {
        link.download = receivedFile.originalName + '.enc';
      } else {
        link.download = receivedFile.originalName;
      }

      // Trigger download
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);

      const message = receivedFile.type === 'encrypted' 
        ? 'Encrypted file downloaded successfully! You can decrypt it using the Decrypt tab.'
        : 'File downloaded successfully!';

      Alert.alert('Success', message);
    } catch (error) {
      console.error('Download error:', error);
      Alert.alert('Error', 'Failed to download file');
    }
  };

  const formatFileSize = (bytes) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const getTimeRemaining = (expiresAt) => {
    const now = new Date();
    const expiry = new Date(expiresAt);
    const diff = expiry - now;

    if (diff <= 0) return 'Expired';

    const hours = Math.floor(diff / (1000 * 60 * 60));
    const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));

    if (hours > 0) {
      return `${hours}h ${minutes}m remaining`;
    }
    return `${minutes}m remaining`;
  };

  const resetSearch = () => {
    if (receivedFile && receivedFile.downloadUrl) {
      URL.revokeObjectURL(receivedFile.downloadUrl);
    }

    setShareCode('');
    setReceivedFile(null);
    setFileType(null);
  };

  return (
    <SafeAreaView style={[styles.container, { backgroundColor: theme.colors.background }]}>
      <ScrollView 
        style={styles.scrollView}
        showsVerticalScrollIndicator={false}
        contentContainerStyle={styles.contentContainer}
      >
        {/* Header */}
        <Animated.View
          style={[
            styles.headerContainer,
            {
              opacity: fadeAnim,
              transform: [{ translateY: slideAnim }],
            }
          ]}
        >
          <LinearGradient
            colors={isDarkMode ? ['rgba(255,255,255,0.1)', 'rgba(255,255,255,0.05)'] : ['rgba(147, 51, 234, 0.1)', 'rgba(168, 85, 247, 0.1)']}
            style={styles.headerGradient}
          >
            <Text style={[styles.headerTitle, { color: theme.colors.onSurface }]}>
              📥 Receive Files
            </Text>
            <Text style={[styles.headerSubtitle, { color: theme.colors.onSurfaceVariant }]}>
              Enter a share code to access and download files
            </Text>
          </LinearGradient>
        </Animated.View>

        {/* Code Input Section */}
        <Animated.View
          style={[
            styles.inputSection,
            {
              opacity: fadeAnim,
              transform: [{ translateY: slideAnim }],
            }
          ]}
        >
          <LinearGradient
            colors={isDarkMode ? ['rgba(255,255,255,0.1)', 'rgba(255,255,255,0.05)'] : ['rgba(147, 51, 234, 0.05)', 'rgba(168, 85, 247, 0.05)']}
            style={styles.inputCard}
          >
            <Text style={[styles.inputLabel, { color: theme.colors.onSurface }]}>
              📝 Enter Share Code
            </Text>
            <Text style={[styles.inputHint, { color: theme.colors.onSurfaceVariant }]}>
              Enter the 6-8 character code you received
            </Text>

            <View style={[styles.inputContainer, { borderColor: theme.colors.outline }]}>
              <TextInput
                style={[styles.codeInput, { color: theme.colors.onSurface }]}
                value={shareCode}
                onChangeText={setShareCode}
                placeholder="Enter 6-8 character code"
                placeholderTextColor={theme.colors.onSurfaceVariant}
                autoCapitalize="characters"
                maxLength={8}
                autoCorrect={false}
              />
            </View>

            <TouchableOpacity 
              style={[styles.accessButton, { opacity: isLoading ? 0.6 : 1 }]}
              onPress={accessSharedFile}
              disabled={isLoading}
              activeOpacity={0.8}
            >
              <LinearGradient
                colors={['#9333ea', '#a855f7']}
                style={styles.accessButtonGradient}
              >
                <Text style={styles.accessButtonText}>
                  {isLoading ? '🔍 Searching...' : '📥 Access File'}
                </Text>
              </LinearGradient>
            </TouchableOpacity>

            {/* Debug Test Button */}
            <TouchableOpacity 
              style={[styles.testButton, { marginTop: 10, padding: 10, borderRadius: 8, backgroundColor: isDarkMode ? 'rgba(255,255,255,0.1)' : 'rgba(147, 51, 234, 0.1)' }]}
              onPress={testStorageAccess}
              activeOpacity={0.8}
            >
              <Text style={[styles.testButtonText, { color: theme.colors.primary, textAlign: 'center' }]}>
                🔧 Test Storage
              </Text>
            </TouchableOpacity>
          </LinearGradient>
        </Animated.View>

        {/* File Details Section */}
        {receivedFile && (
          <Animated.View
            style={[
              styles.fileDetailsSection,
              {
                opacity: fadeAnim,
                transform: [{ translateY: slideAnim }],
              }
            ]}
          >
            <LinearGradient
              colors={isDarkMode ? ['rgba(255,255,255,0.1)', 'rgba(255,255,255,0.05)'] : ['rgba(147, 51, 234, 0.05)', 'rgba(168, 85, 247, 0.05)']}
              style={styles.fileCard}
            >
              <View style={styles.fileHeader}>
                <Text style={[styles.fileFoundTitle, { color: theme.colors.onSurface }]}>
                  ✅ File Found!
                </Text>
                <View style={[styles.fileTypeBadge, { 
                  backgroundColor: fileType === 'encrypted' 
                    ? (isDarkMode ? 'rgba(255, 87, 108, 0.2)' : 'rgba(240, 147, 251, 0.2)')
                    : (isDarkMode ? 'rgba(67, 233, 123, 0.2)' : 'rgba(56, 249, 215, 0.2)')
                }]}>
                  <Text style={[styles.fileTypeBadgeText, { 
                    color: fileType === 'encrypted' ? '#f55a6c' : '#38f9d7'
                  }]}>
                    {fileType === 'encrypted' ? '🔒 Encrypted' : '📄 Unencrypted'}
                  </Text>
                </View>
              </View>

              <View style={styles.fileInfo}>
                <View style={styles.fileIconContainer}>
                  <Text style={styles.fileIcon}>
                    {receivedFile.name.includes('.pdf') ? '📄' :
                     receivedFile.name.includes('.jpg') || receivedFile.name.includes('.png') ? '🖼️' :
                     receivedFile.name.includes('.doc') ? '📝' :
                     receivedFile.name.includes('.zip') ? '📦' : '📄'}
                  </Text>
                </View>
                <View style={styles.fileDetails}>
                  <Text style={[styles.fileName, { color: theme.colors.onSurface }]}>
                    {receivedFile.originalName}
                  </Text>
                  <Text style={[styles.fileSize, { color: theme.colors.onSurfaceVariant }]}>
                    {formatFileSize(receivedFile.size)}
                  </Text>
                  <Text style={[styles.fileExpiry, { color: theme.colors.onSurfaceVariant }]}>
                    {getTimeRemaining(receivedFile.expiresAt)}
                  </Text>
                </View>
              </View>

              <View style={styles.actionButtons}>
                <TouchableOpacity 
                  style={styles.downloadButton}
                  onPress={downloadFile}
                  activeOpacity={0.8}
                >
                  <LinearGradient
                    colors={['#9333ea', '#a855f7']}
                    style={styles.downloadButtonGradient}
                  >
                    <Text style={styles.downloadButtonText}>
                      ⬇️ Download File
                    </Text>
                  </LinearGradient>
                </TouchableOpacity>

                <TouchableOpacity 
                  style={[styles.resetButton, { borderColor: theme.colors.outline }]}
                  onPress={resetSearch}
                  activeOpacity={0.8}
                >
                  <Text style={[styles.resetButtonText, { color: theme.colors.onSurfaceVariant }]}>
                    🔄 Search Another
                  </Text>
                </TouchableOpacity>
              </View>
            </LinearGradient>
          </Animated.View>
        )}

        {/* Instructions */}
        <Animated.View
          style={[
            styles.instructionsSection,
            {
              opacity: fadeAnim,
              transform: [{ translateY: slideAnim }],
            }
          ]}
        >
          <LinearGradient
            colors={isDarkMode ? ['rgba(255,255,255,0.05)', 'rgba(255,255,255,0.02)'] : ['rgba(147, 51, 234, 0.03)', 'rgba(168, 85, 247, 0.03)']}
            style={styles.instructionsCard}
          >
            <Text style={[styles.instructionsTitle, { color: theme.colors.onSurface }]}>
              📋 How to Use
            </Text>
            <Text style={[styles.instructionsText, { color: theme.colors.onSurfaceVariant }]}>
              • Enter the share code you received from the sender{'\n'}
              • Codes are 6 characters for unencrypted files{'\n'}
              • Codes are 8 characters for encrypted files{'\n'}
              • Click "Access File" to retrieve and download{'\n'}
              • Files expire based on sender's settings
            </Text>
          </LinearGradient>
        </Animated.View>
      </ScrollView>
    </SafeAreaView>
  );
};

